 "purposes": [
  {
   "id": "praise",
   "name": "Praise",
   "says": "Paul sings about being chosen before he explains anything.",
   "misread": "A song is not a sorting machine."
  },
  {
   "id": "comfort",
   "name": "Comfort",
   "says": "Jesus speaks about His sheep to people who need to know they are safe.",
   "misread": "A promise is not a riddle."
  },
  {
   "id": "warn",
   "name": "Warning",
   "says": "Hebrews shakes readers who are drifting.",
   "misread": "A warning is not a verdict."
  },
  {
   "id": "answer",
   "name": "Answer",
   "says": "Paul argues with a voice that says God is unfair.",
   "misread": null
  }
 ],
 "purposeOf": {
  "01": {
   "kinds": [
    "praise"
   ],
   "close": "Ephesians 1 was written to make you praise."
  },
  "02": {
   "kinds": [
    "comfort"
   ],
   "close": "Romans 8 was written so that you would know nothing can separate you from God’s love."
  },
  "03": {
   "kinds": [
    "answer"
   ],
   "close": "Romans 9 answers the charge that God is unfair, and it humbles everyone who reads it."
  },
  "04": {
   "kinds": [
    "comfort"
   ],
   "close": "John 6 and 10 were spoken so that sheep would know they are safe."
  },
  "05": {
   "kinds": [
    "warn"
   ],
   "close": "Hebrews 6 warns drifters so that they stay."
  },
  "06": {
   "kinds": [
    "comfort"
   ],
   "close": "First John was written “so that you may know”."
  },
  "07": {
   "kinds": [
    "warn",
    "comfort"
   ],
   "close": "Mark 3 shows that the One who warns of a single unforgiven sin also promises forgiveness for all the rest."
  }
 },
